1215		if (l2cap_br_server_lookup_psm(hdev, server->psm)) {
1216			LOG_DBG("PSM already registered");
1217			return -EADDRINUSE;
1218		}
1219	
1220		LOG_DBG("PSM 0x%04x", server->psm);
1221	
1222		sys_slist_append(&hdev->l2cap_br_ctx->br_servers, &server->node);
1223	
1224		return 0;
